 void patientResultUI()throws Exception{Store s=new Store(getTargetContext());String code="TEST-SCORE-"+System.currentTimeMillis(),pid=s.addPatient(code,""),id=s.createForPatient(pid,Store.today());Map<String,String>values=valid();values.put("patient",code);s.save(id,Store.payload(values,true).toString(),"test score");Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->((View)find(a,code).getParent()).performClick());waitForIdleSync();runOnMainSync(()->find(a,"记录今天").performClick());waitForIdleSync();runOnMainSync(()->find(a,"3 / 21 · PSQI").performClick());waitForIdleSync();runOnMainSync(()->check(find(a,"3 / 21")!=null,"daily result UI correct"));runOnMainSync(()->find(a,"查看／修改答案").performClick());waitForIdleSync();runOnMainSync(()->{for(View v:all(a.getWindow().getDecorView()))if(v instanceof EditText){((EditText)v).setText("15");break;}});check(!Store.completed(s.get(id).data),"daily answer edit returns to draft");runOnMainSync(()->find(a,"完成并查看得分").performClick());waitForIdleSync();check(new JSONObject(s.get(id).data).getInt("total")==2,"recalculation reflects edited daily answer");runOnMainSync(()->find(a,"返回档案").performClick());waitForIdleSync();check(s.meta(id).patientId.equals(pid),"results return to same patient");s.close();}


 Map<String,String> generic(String scale,String code,int value){Map<String,String>a=Scales.empty(scale);a.put("patient",code);a.put("assessmentTime","12:30");a.put("rater","R01");for(Scales.Item item:Scales.get(scale).items)a.put(item.key,""+Math.min(value,item.max()));return a;}
 void multi()throws Exception{Context c=getTargetContext();String name="multi-"+UUID.randomUUID()+".db",other="multi-"+UUID.randomUUID()+".db";Store s=new Store(c,name),dest=new Store(c,other);try{String pid=s.addPatient("0001","测试甲"),pid2=s.addPatient("0002","测试乙");String date="2026-11-10";for(String scale:Scales.IDS){String id=s.createForPatient(pid,date,scale);Map<String,String>a=scale.equals("PSQI")?valid():generic(scale,"0001",10);a.put("patient","0001");s.save(id,Store.payload(a,true,scale).toString(),"complete");check(s.createForPatient(pid,date,scale).equals(id),"same date scale reopens "+scale);check(s.meta(id).scale.equals(scale),"scale metadata "+scale);check(new JSONObject(s.get(id).data).getInt("total")== (scale.equals("PSQI")?3:Scales.get(scale).max),"score "+scale);}check(s.patientRecords(pid,false).size()==5,"five independent scales same day");String second=s.createForPatient(pid,"2026-11-11","NRS");s.save(second,Store.payload(generic("NRS","0001",2),true,"NRS").toString(),"complete");s.createForPatient(pid2,date,"NRS");String trash=s.createForPatient(pid,"2026-11-12","NRS");s.save(trash,Store.payload(generic("NRS","0001",0),true,"NRS").toString(),"complete");s.trash(trash,true);JSONObject snapshot=s.backup();Store.validateBackup(snapshot);Reports.Filter f=new Reports.Filter(null,"","");Reports.Stat nrs=Reports.stats(snapshot,f).get(1);check(nrs.n==2&&nrs.patients==1,"draft trash excluded and distinct people");check(nrs.mean==6&&nrs.median==6&&Math.abs(nrs.sd-Math.sqrt(32))<1e-9,"sample statistics");check(Reports.stats(snapshot,new Reports.Filter(pid,"2026-11-10","2026-11-10")).get(1).n==1,"inclusive date filtering");check(Reports.stats(snapshot,new Reports.Filter(pid2,"","")).get(1).mean==null,"missing scores not zero");List<Xlsx.Sheet> sheets=Reports.workbook(snapshot,f);check(sheets.size()==7,"seven sheets");check(sheets.get(2).rows.get(1).get(0) instanceof String,"patient codes textual");java.io.File output=new java.io.File(c.getExternalFilesDir(null),"verified-multiscale.xlsx");Xlsx.write(new java.io.FileOutputStream(output),sheets);try(java.util.zip.ZipFile z=new java.util.zip.ZipFile(output)){check(z.getEntry("xl/worksheets/sheet7.xml")!=null,"xlsx complete");for(java.util.Enumeration<? extends java.util.zip.ZipEntry>e=z.entries();e.hasMoreElements();){java.util.zip.ZipEntry entry=e.nextElement();javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(z.getInputStream(entry));}check(true,"all xlsx parts well formed XML");}int[] restored=dest.restore(snapshot);check(restored[0]==8,"all records restored");check(Reports.stats(dest.backup(),f).get(1).mean==6,"restored statistics unchanged");dest.restore(snapshot);check(dest.rows(false).size()==7,"repeat import deduplicated");JSONObject conflict=new JSONObject(snapshot.toString());JSONArray records=conflict.getJSONArray("records");for(int i=0;i<records.length();i++)if(records.getJSONObject(i).getString("id").equals(second))records.getJSONObject(i).getJSONObject("data").getJSONObject("answers").put("note","copy");dest.restore(conflict);check(Reports.stats(dest.backup(),f).get(1).n==2,"restored copy not double counted");check(dest.csv().contains("HAMD-17"),"multiscale CSV works");boolean rejects=false;try{dest.save(second,Store.payload(generic("AIS8","0001",1),true,"AIS8").toString(),"wrong scale");}catch(Exception e){rejects=true;}check(rejects,"existing scale immutable");
  // Real version-2 schema upgrade and backup compatibility.
  JSONObject v2=new JSONObject(snapshot.toString());v2.put("version",2);JSONArray psqi=new JSONArray();for(int i=0;i<records.length();i++)if(records.getJSONObject(i).getString("scale").equals("PSQI"))psqi.put(records.getJSONObject(i));v2.put("records",psqi);Store.validateBackup(v2);check(true,"version2 backup accepted");
 }finally{s.close();dest.close();c.deleteDatabase(name);c.deleteDatabase(other);}}
