 void migration2()throws Exception{Context c=getTargetContext();String name="v2upgrade-"+UUID.randomUUID()+".db";Store s=new Store(c,name);String pid=s.addPatient("V2-001","旧档案"),id=s.createForPatient(pid,"2026-11-12");Map<String,String>a=valid();a.put("patient","V2-001");s.save(id,Store.payload(a,true).toString(),"before upgrade");String original=s.get(id).data;JSONObject backup=s.backup();backup.put("version",2);s.close();android.database.sqlite.SQLiteDatabase old=c.openOrCreateDatabase(name,0,null);old.execSQL("DROP INDEX IF EXISTS patient_scale_days");old.execSQL("ALTER TABLE record_meta RENAME TO record_meta_new");old.execSQL("CREATE TABLE record_meta(record_id TEXT PRIMARY KEY REFERENCES records(id),patient_id TEXT NOT NULL REFERENCES patients(id),day TEXT NOT NULL)");old.execSQL("INSERT INTO record_meta SELECT record_id,patient_id,day FROM record_meta_new");old.execSQL("DROP TABLE record_meta_new");old.execSQL("CREATE INDEX patient_days ON record_meta(patient_id,day)");old.setVersion(2);old.close();Store upgraded=new Store(c,name);try{check(upgraded.getWritableDatabase().getVersion()==4,"v2 database upgrades");check(upgraded.get(id).data.equals(original),"v2 payload unchanged");check(upgraded.meta(id).scale.equals("PSQI"),"v2 defaults to PSQI");check(upgraded.meta(id).day.equals("2026-11-12"),"v2 date preserved");String nrs=upgraded.createForPatient(pid,"2026-11-12","NRS");check(!nrs.equals(id),"new scale same date after upgrade");int[]result=upgraded.restore(backup);check(result[2]==1,"v2 backup restores as safe copy");check(upgraded.patientRecords(pid,false).size()==3,"v2 existing data preserved after restore");}finally{upgraded.close();c.deleteDatabase(name);}}


