 void keyboard()throws Exception{Store s=new Store(getTargetContext());String code="UI-IME-"+System.currentTimeMillis(),pid=s.addPatient(code,"键盘测试");Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->((View)find(a,"键盘测试 · "+code).getParent()).performClick());waitForIdleSync();runOnMainSync(()->find(a,"记录今天").performClick());waitForIdleSync();runOnMainSync(()->find(a,"填写 PSQI").performClick());waitForIdleSync();final EditText[]target=new EditText[1];runOnMainSync(()->{for(View v:all(a.getWindow().getDecorView()))if(v instanceof EditText){target[0]=(EditText)v;break;}target[0].requestFocus();target[0].setText("25");((android.view.inputmethod.InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(target[0],android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});Thread.sleep(700);waitForIdleSync();runOnMainSync(()->{android.graphics.Rect window=new android.graphics.Rect(),field=new android.graphics.Rect();a.getWindow().getDecorView().getWindowVisibleDisplayFrame(window);check(target[0].getGlobalVisibleRect(field),"focused field visible");check(field.bottom<=window.bottom,"keyboard does not cover focused field");layoutCheck(a);});check(Store.answers(s.patientRecords(pid,false).get(0).data).get("q2").equals("25"),"input saved with keyboard visible");snap("ui-keyboard");runOnMainSync(()->((android.view.inputmethod.InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(target[0].getWindowToken(),0));s.close();}


 void continuous()throws Exception{
  Store s=new Store(getTargetContext());String code="SCROLL-"+System.currentTimeMillis(),pid=s.addPatient(code,"连续填写测试");
  for(String scale:Scales.IDS){String id=s.createForPatient(pid,Store.today(),scale);Map<String,String>v=scale.equals("PSQI")?valid():generic(scale,code,1);v.put("patient",code);s.save(id,Store.payload(v,false,scale).toString(),"test fixture");}
  Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
  runOnMainSync(()->((View)find(a,"连续填写测试 · "+code).getParent()).performClick());waitForIdleSync();
  for(String scale:Scales.IDS){runOnMainSync(()->find(a,"记录今天").performClick());waitForIdleSync();runOnMainSync(()->find(a,"继续草稿 · "+Scales.get(scale).shortName).performClick());waitForIdleSync();
   final ScrollView[]scroll={null};final EditText[]note={null};
   runOnMainSync(()->{int groups=0;for(View v:all(a.getWindow().getDecorView())){if(v instanceof ScrollView)scroll[0]=(ScrollView)v;if(v instanceof RadioGroup)groups++;if(v instanceof EditText)note[0]=(EditText)v;if(v instanceof Button)check(!((Button)v).getText().toString().equals("下一步"),"no page navigation");}check(groups==(scale.equals("PSQI")?14:Scales.get(scale).items.length),"all questions on one page "+scale);scroll[0].setSmoothScrollingEnabled(false);scroll[0].fullScroll(View.FOCUS_DOWN);});waitForIdleSync();
   runOnMainSync(()->{check(scroll[0].getScrollY()>0,"can scroll to form end "+scale);check(find(a,"完成并查看得分").getGlobalVisibleRect(new android.graphics.Rect()),"completion reachable by scrolling "+scale);note[0].setText("滑到底部后填写备注");});waitForIdleSync();
   String id=s.createForPatient(pid,Store.today(),scale);check(Store.answers(s.get(id).data).get("note").equals("滑到底部后填写备注"),"bottom answer immediately saved "+scale);
   if(scale.equals("PSQI"))snap("ui-continuous-bottom");
   runOnMainSync(()->{scroll[0].fullScroll(View.FOCUS_UP);});waitForIdleSync();runOnMainSync(()->check(scroll[0].getScrollY()==0,"return to first question "+scale));
   if(scale.equals("PSQI")||scale.equals("HAMD17")){final int[]pos=new int[2];runOnMainSync(()->scroll[0].getLocationOnScreen(pos));float x=pos[0]+scroll[0].getWidth()/2f,y=pos[1]+scroll[0].getHeight()*0.8f;long down=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(down,down,MotionEvent.ACTION_DOWN,x,y,0));for(int n=1;n<=12;n++){SystemClock.sleep(16);sendPointerSync(MotionEvent.obtain(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_MOVE,x,y-scroll[0].getHeight()*0.5f*n/12,0));}sendPointerSync(MotionEvent.obtain(down,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,y-scroll[0].getHeight()*0.5f,0));SystemClock.sleep(250);waitForIdleSync();runOnMainSync(()->check(scroll[0].getScrollY()>0,"touch swipe moves through questions "+scale));}
   runOnMainSync(()->find(a,"完成并查看得分").performClick());waitForIdleSync();check(Store.completed(s.get(id).data),"continuous form completes "+scale);check(new JSONObject(s.get(id).data).getInt("total")== (scale.equals("PSQI")?3:Scales.get(scale).items.length),"score unchanged "+scale);
   runOnMainSync(()->find(a,"返回档案").performClick());waitForIdleSync();
  }s.close();
 }

 long sqlCount(Store s,String sql,String id){try(Cursor c=s.getReadableDatabase().rawQuery(sql,new String[]{id})){c.moveToFirst();return c.getLong(0);}}
 int purge(Store s,String pid)throws Exception{s.trashPatient(pid,true);return s.deletePatient(pid);}
 void deletePatient()throws Exception{
  Context c=getTargetContext();String name="delete-test-"+UUID.randomUUID()+".db";Store s=new Store(c,name);
  try{String pid=s.addPatient("DELETE-001","待删除测试甲"),other=s.addPatient("KEEP-002","保留测试乙"),empty=s.addPatient("EMPTY-003","");
   String keep=s.createForPatient(other,Store.today(),"NRS");s.save(keep,Store.payload(generic("NRS","KEEP-002",4),true,"NRS").toString(),"fixture");String keepData=s.get(keep).data;int keepHistory=s.history(keep).length();
   List<String>ids=new ArrayList<>();for(String scale:Scales.IDS){String id=s.createForPatient(pid,"2026-11-10",scale);Map<String,String>a=scale.equals("PSQI")?valid():generic(scale,"DELETE-001",1);a.put("patient","DELETE-001");s.save(id,Store.payload(a,true,scale).toString(),"fixture");ids.add(id);}
   String draft=s.createForPatient(pid,"2026-11-11","NRS");ids.add(draft);String trash=s.createForPatient(pid,"2026-11-12","AIS8");s.trash(trash,true);ids.add(trash);s.trashPatient(pid,true);JSONObject before=s.backup();long revision=s.revisionCount();
   s.getWritableDatabase().execSQL("CREATE TRIGGER fail_patient_delete BEFORE DELETE ON patients BEGIN SELECT RAISE(ABORT,'test failure'); END");boolean failed=false;try{purge(s,pid);}catch(Exception e){failed=true;}
   check(failed,"delete failure injected after child rows removed");check(s.patient(pid)!=null&&s.patientRecords(pid,false).size()==6&&s.patientRecords(pid,true).size()==1,"failed delete restores patient and all records");check(s.revisionCount()==revision,"failed deletion rolls back change counter");check(s.backup().getJSONArray("records").toString().equals(before.getJSONArray("records").toString()),"rollback preserves all answers and histories");s.getWritableDatabase().execSQL("DROP TRIGGER fail_patient_delete");
   check(purge(s,pid)==7,"one action deletes all dates scales draft and trash");check(s.patient(pid)==null,"patient removed");for(String id:ids){check(s.get(id)==null&&s.history(id).length()==0,"record and answer history removed");check(sqlCount(s,"SELECT COUNT(*) FROM record_meta WHERE record_id=?",id)==0&&sqlCount(s,"SELECT COUNT(*) FROM meta_events WHERE record_id=?",id)==0,"record date links and history removed");}
   check(sqlCount(s,"SELECT COUNT(*) FROM patient_events WHERE patient_id=?",pid)==0,"patient name history removed");check(s.get(keep).data.equals(keepData)&&s.history(keep).length()==keepHistory&&s.patient(other)!=null,"other patient untouched");check(s.revisionCount()>revision,"deletion invalidates prior backup status");JSONObject after=s.backup();Store.validateBackup(after);check(!after.toString().contains("DELETE-001")&&!s.csv().contains("DELETE-001"),"new backup and export omit deleted patient");check(Reports.stats(after,new Reports.Filter(null,"","")).get(1).n==1,"statistics omit deleted records");
   long rev=s.revisionCount();check(purge(s,empty)==0&&s.patient(empty)==null,"empty patient can be deleted");check(s.revisionCount()>rev,"empty deletion advances backup status");s.restore(before);check(s.patient(pid)!=null&&s.get(trash).deleted,"old backup restores intentionally deleted patient and trash");purge(s,pid);purge(s,empty);s.close();s=new Store(c,name);check(s.patient(pid)==null,"deletion persists on reopen");int[]restored=s.restore(before);check(restored[0]==7&&s.patientRecords(pid,false).size()==6&&s.patientRecords(pid,true).size()==1,"previously imported backup can restore deleted patient again");check(s.patient(empty)!=null,"previously imported empty patient can restore again");check(s.get(keep).data.equals(keepData),"restore preserves other patient");int n=s.rows(false).size();s.restore(before);check(s.rows(false).size()==n,"repeated import still deduplicates");
  }finally{s.close();c.deleteDatabase(name);}
 }
 void dialogClick(String label)throws Exception{waitForIdleSync();android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null)for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label))if(label.contentEquals(node.getText())&&node.isClickable()){check(node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK),"dialog action "+label);waitForIdleSync();return;}throw new AssertionError("Dialog button not found "+label);}

 void recycle()throws Exception{Context c=getTargetContext();String name="recycle-"+UUID.randomUUID()+".db",destName="recycle-restore-"+UUID.randomUUID()+".db";Store s=new Store(c,name),dest=new Store(c,destName);try{
  String pid=s.addPatient("RECYCLE-001","测试甲"),other=s.addPatient("OTHER-002","测试乙"),empty=s.addPatient("EMPTY-003","");List<String>ids=new ArrayList<>();Map<String,String>original=new HashMap<>(),histories=new HashMap<>();for(String scale:Scales.IDS){String id=s.createForPatient(pid,"2026-11-10",scale);Map<String,String>a=scale.equals("PSQI")?valid():generic(scale,"RECYCLE-001",2);a.put("patient","RECYCLE-001");s.save(id,Store.payload(a,true,scale).toString(),"fixture");ids.add(id);original.put(id,s.get(id).data);histories.put(id,s.history(id).toString());}String oldTrash=s.createForPatient(pid,"2026-11-11","NRS");s.trash(oldTrash,true);String keep=s.createForPatient(other,"2026-11-10","NRS");s.save(keep,Store.payload(generic("NRS","OTHER-002",8),true,"NRS").toString(),"fixture");String keepData=s.get(keep).data;
  boolean blocked=false;try{s.deletePatient(pid);}catch(Exception e){blocked=true;}check(blocked,"cannot permanently delete active patient");long before=s.revisionCount();s.getWritableDatabase().execSQL("CREATE TRIGGER fail_trash BEFORE INSERT ON patient_events BEGIN SELECT RAISE(ABORT,'test failure'); END");boolean failed=false;try{s.trashPatient(pid,true);}catch(Exception e){failed=true;}check(failed&&!s.patient(pid).deleted&&s.revisionCount()==before,"failed move rolls back state and revision");s.getWritableDatabase().execSQL("DROP TRIGGER fail_trash");s.trashPatient(pid,true);s.trashPatient(empty,true);check(s.patient(pid).deleted&&s.patients().size()==1&&s.patients(true).size()==2,"whole patient hidden including empty profiles");check(s.rows(false).size()==1&&s.rows(true).isEmpty(),"home counts exclude recycled patient's records");for(String id:ids){check(s.get(id).data.equals(original.get(id))&&s.history(id).toString().equals(histories.get(id)),"answers score and history retained "+id);}check(s.revisionCount()>before,"move marks backup stale");JSONObject backup=s.backup();Store.validateBackup(backup);check(backup.getInt("version")==4&&backup.getJSONArray("patients").length()==3&&backup.getJSONArray("records").length()==7,"backup includes entire recycle bin");check(Reports.stats(backup,new Reports.Filter(null,"","")).get(1).mean==8,"statistics exclude recycled patient");check(!s.csv().contains("RECYCLE-001"),"regular export excludes recycled patient");check(Reports.workbook(backup,new Reports.Filter(null,"","")).get(1).rows.size()==2,"patient sheet excludes archived profiles");boolean noCreate=false;try{s.createForPatient(pid,"2026-11-12","NRS");}catch(Exception e){noCreate=true;}check(noCreate,"cannot create new record under archived patient");boolean duplicate=false;try{s.addPatient("RECYCLE-001","");}catch(Exception e){duplicate=e.getMessage().contains("回收站");}check(duplicate,"duplicate code prompts restore from recycle bin");
  s.close();s=new Store(c,name);check(s.patient(pid).deleted&&s.get(ids.get(0)).data.equals(original.get(ids.get(0))),"recycle state retained across reopen");dest.restore(new JSONObject(BackupFile.decode(BackupFile.encode(backup.toString()))));check(dest.patient(pid).deleted&&dest.patient(empty).deleted&&dest.rows(false).size()==1,"backup restores recycle state including empty patient");dest.trashPatient(pid,false);check(dest.patientRecords(pid,false).size()==5&&dest.get(oldTrash).deleted,"restore whole patient preserves earlier individual trash");dest.restore(backup);check(!dest.patient(pid).deleted,"reimport does not overwrite current restored state");s.trashPatient(pid,false);s.trashPatient(empty,false);check(s.patients().size()==3&&s.patientRecords(pid,false).size()==5&&s.get(oldTrash).deleted,"one click restores original patient and records");check(Reports.stats(s.backup(),new Reports.Filter(pid,"2026-11-10","2026-11-10")).get(1).mean==2,"patient plus date filter exact after restoration");check(s.get(keep).data.equals(keepData),"other patient unchanged");boolean activePurge=false;try{s.deleteRecord(ids.get(0));}catch(Exception e){activePurge=true;}check(activePurge,"record purge restricted to recycle bin");s.deleteRecord(oldTrash);check(s.get(oldTrash)==null&&s.history(oldTrash).length()==0,"explicit purge clears individually recycled record");s.trashPatient(pid,true);s.deletePatient(pid);check(s.patient(pid)==null&&s.get(ids.get(0))==null&&s.patient(other)!=null,"explicit second delete purges archived patient only");JSONObject bad=new JSONObject(backup.toString());bad.getJSONArray("patients").getJSONObject(0).put("deleted","true");boolean rejects=false;try{Store.validateBackup(bad);}catch(Exception e){rejects=true;}check(rejects,"bad recycle backup state rejected");
 }finally{s.close();dest.close();c.deleteDatabase(name);c.deleteDatabase(destName);}}
 void cardAction(Activity a,String name,String action){View card=(View)find(a,name).getParent();for(View v:all(card))if(v instanceof Button&&((Button)v).getText().toString().equals(action)){v.performClick();return;}throw new AssertionError("missing card action "+action);}
 void recycleUI()throws Exception{Store s=new Store(getTargetContext());String code="RECYCLE-UI-"+System.currentTimeMillis(),name="回收站测试 · "+code,pid=s.addPatient(code,"回收站测试");String id=s.createForPatient(pid,"2026-11-10","NRS"),trash=s.createForPatient(pid,"2026-11-11","AIS8");s.trash(trash,true);Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->((View)find(a,name).getParent()).performLongClick());waitForIdleSync();dialogClick("取消");check(!s.patient(pid).deleted,"cancel move keeps active");runOnMainSync(()->((View)find(a,name).getParent()).performClick());waitForIdleSync();runOnMainSync(()->find(a,"病人移入回收站").performClick());waitForIdleSync();dialogClick("移入回收站");check(s.patient(pid).deleted&&s.get(id)!=null,"move preserves records");runOnMainSync(()->find(a,"更多").performClick());waitForIdleSync();runOnMainSync(()->find(a,"回收站").performClick());waitForIdleSync();snap("ui-recycle-bin");runOnMainSync(()->cardAction(a,name,"永久删除病人"));waitForIdleSync();dialogClick("取消");check(s.patient(pid).deleted&&s.get(id)!=null,"cancel purge preserves recycled data");runOnMainSync(()->cardAction(a,name,"恢复整个病人"));waitForIdleSync();check(!s.patient(pid).deleted&&s.get(trash).deleted,"restore UI keeps previous record trash");runOnMainSync(()->find(a,"返回病人列表").performClick());waitForIdleSync();runOnMainSync(()->((View)find(a,name).getParent()).performLongClick());waitForIdleSync();dialogClick("移入回收站");runOnMainSync(()->find(a,"更多").performClick());waitForIdleSync();runOnMainSync(()->find(a,"回收站").performClick());waitForIdleSync();runOnMainSync(()->cardAction(a,name,"永久删除病人"));waitForIdleSync();dialogClick("确认永久删除");check(s.patient(pid)==null&&s.get(id)==null&&s.get(trash)==null,"purge only after recycle-bin confirmation");s.close();}
 void migration3()throws Exception{Context c=getTargetContext();String name="v3upgrade-"+UUID.randomUUID()+".db";Store s=new Store(c,name);String pid=s.addPatient("V3-001","旧档案"),id=s.createForPatient(pid,"2026-11-12","NRS");s.save(id,Store.payload(generic("NRS","V3-001",3),true,"NRS").toString(),"fixture");String original=s.get(id).data;JSONObject backup=s.backup();backup.put("version",3);for(int i=0;i<backup.getJSONArray("patients").length();i++)backup.getJSONArray("patients").getJSONObject(i).remove("deleted");s.close();android.database.sqlite.SQLiteDatabase old=c.openOrCreateDatabase(name,0,null);old.execSQL("ALTER TABLE patients DROP COLUMN deleted");old.setVersion(3);old.close();Store upgraded=new Store(c,name);try{check(upgraded.getWritableDatabase().getVersion()==4,"v3 upgrades to v4");check(upgraded.get(id).data.equals(original)&&!upgraded.patient(pid).deleted,"v3 answers retained and patient active");Store.validateBackup(backup);upgraded.restore(backup);check(upgraded.patientRecords(pid,false).size()==2,"v3 backup imports as safe copy");}finally{upgraded.close();c.deleteDatabase(name);}}
 android.view.accessibility.AccessibilityNodeInfo findEditable(android.view.accessibility.AccessibilityNodeInfo node){if(node==null)return null;if(node.isEditable())return node;for(int i=0;i<node.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo found=findEditable(node.getChild(i));if(found!=null)return found;}return null;}
 void filterUI()throws Exception{Store s=new Store(getTargetContext());String code="FILTER-"+System.currentTimeMillis(),pid=s.addPatient(code,"筛选测试甲"),other=s.addPatient(code+"B","筛选测试乙");String id=s.createForPatient(pid,"2026-11-10","NRS"),oid=s.createForPatient(other,"2026-11-10","NRS");s.save(id,Store.payload(generic("NRS",code,3),true,"NRS").toString(),"fixture");s.save(oid,Store.payload(generic("NRS",code+"B",9),true,"NRS").toString(),"fixture");Activity a=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();runOnMainSync(()->find(a,"统计").performClick());waitForIdleSync();runOnMainSync(()->find(a,"病人：全部病人").performClick());waitForIdleSync();android.view.accessibility.AccessibilityNodeInfo input=null;for(int retry=0;retry<30;retry++){input=findEditable(getUiAutomation().getRootInActiveWindow());if(input!=null)break;SystemClock.sleep(100);}check(input!=null,"patient search field ready");Bundle searchArgs=new Bundle();searchArgs.putCharSequence(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,code);boolean searched=input.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SET_TEXT,searchArgs);check(searched,"search patient selector by code");waitForIdleSync();dialogClick("筛选测试甲 · "+code);runOnMainSync(()->{check(find(a,"病人：筛选测试甲 · "+code)!=null,"selected patient displayed");check(find(a,"3.00")!=null,"statistics reflect only selected patient");});snap("ui-patient-filter");runOnMainSync(()->find(a,"导出筛选结果 Excel .xlsx").performClick());java.io.File staged=new java.io.File(getTargetContext().getCacheDir(),"export-stage.bin");boolean ready=false;for(int n=0;n<50;n++){SystemClock.sleep(100);try(java.util.zip.ZipFile z=new java.util.zip.ZipFile(staged)){ready=z.getEntry("xl/worksheets/sheet7.xml")!=null;if(ready)break;}catch(Exception ignored){}}check(ready,"filtered Excel generated from UI export");try(java.util.zip.ZipFile z=new java.util.zip.ZipFile(staged)){for(int sheet:new int[]{2,3,4,5}){java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(java.io.InputStream in=z.getInputStream(z.getEntry("xl/worksheets/sheet"+sheet+".xml"))){byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);}String xml=bytes.toString("UTF-8");check(xml.contains(code)&&!xml.contains(code+"B"),"export sheet "+sheet+" contains only selected patient");}}getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);SystemClock.sleep(300);waitForIdleSync();runOnMainSync(()->find(a,"导出筛选结果 CSV").performClick());SystemClock.sleep(200);String csv=new String(java.nio.file.Files.readAllBytes(staged.toPath()),StandardCharsets.UTF_8);check(csv.contains(code)&&!csv.contains(code+"B")&&csv.contains("记录ID"),"CSV UI export uses same patient filter");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);waitForIdleSync();s.close();}
